    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            TotalStars = 14, RatingCount = 3
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale, then remove from heat.\n5. Stir in egg mixture quickly, tossing to coat without scrambling.",
            TotalStars = 10, RatingCount = 2
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pot.\n4. Add tomatoes, cream, and remaining spices.\n5. Simmer sauce for 15 minutes, add chicken.\n6. Serve over basmati rice.",
            TotalStars = 5, RatingCount = 1
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs",
            Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Mix tamarind paste, fish sauce, and sugar for the sauce.\n3. Stir-fry tofu until golden, set aside.\n4. Scramble eggs in the wok.\n5. Add noodles and sauce, toss until coated.\n6. Add tofu, bean sprouts, and peanuts.\n7. Serve with lime wedges.",
            TotalStars = 8, RatingCount = 2
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef, lettuce, tomato, and cheese.\n5. Top with sour cream and salsa.",
            TotalStars = 12, RatingCount = 3
        },
        new Recipe
        {
            Id = 6, Title = "Miso Ramen", Category = "Japanese",
            Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSoft-boiled egg\nChashu pork\nGreen onions\nNori\nCorn",
            Steps = "1. Heat chicken broth and dissolve miso paste into it.\n2. Season with soy sauce to taste.\n3. Cook ramen noodles according to package.\n4. Place noodles in a bowl, ladle broth over them.\n5. Top with sliced chashu, soft-boiled egg, nori, corn, and green onions.",
            TotalStars = 9, RatingCount = 2
        }
    };

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalStars += stars;
            recipe.RatingCount++;
        }
    }
}

